const _recite = function recite(){
  const bottleWord = (count) => (count === 1 ? "bottle" : "bottles");
  const verse = (count) => {
    if (count === 0) {
      return [
        "No more bottles of beer on the wall, no more bottles of beer.",
        "Go to the store and buy some more, 99 bottles of beer on the wall.",
      ];
    }
    const secondLine = count === 1
      ? "Take it down and pass it around, no more bottles of beer on the wall."
      : `Take one down and pass it around, ${count - 1} ${bottleWord(count - 1)} of beer on the wall.`;
    return [
      `${count} ${bottleWord(count)} of beer on the wall, ${count} ${bottleWord(count)} of beer.`,
      secondLine,
    ];
  };
  return (initialBottlesCount, takeDownCount) => {
    const lines = [];
    for (let i = 0; i < takeDownCount; i++) {
      if (i > 0) lines.push("");
      lines.push(...verse(initialBottlesCount - i));
    }
    return lines;
  };
};

