const _cost = function cost(){ return (books) => {
  const counts = [0, 0, 0, 0, 0];
  for (const b of books) {
    if (b >= 1 && b <= 5) counts[b - 1] += 1;
  }
  // Price in cents for a set of n distinct books (n * 800 * (1 - discount)).
  const groupPrice = [0, 800, 1520, 2160, 2560, 3000];
  const memo = new Map();
  const solve = (c) => {
    const key = c.join(",");
    if (memo.has(key)) return memo.get(key);
    if (c.every(x => x === 0)) {
      memo.set(key, 0);
      return 0;
    }
    let best = Infinity;
    for (let mask = 1; mask < 32; mask++) {
      const size = (mask.toString(2).match(/1/g) || []).length;
      let valid = true;
      const next = c.slice();
      for (let i = 0; i < 5; i++) {
        if (mask & (1 << i)) {
          if (next[i] === 0) { valid = false; break; }
          next[i] -= 1;
        }
      }
      if (!valid) continue;
      next.sort((a, b) => b - a);
      best = Math.min(best, groupPrice[size] + solve(next));
    }
    memo.set(key, best);
    return best;
  };
  return solve(counts);
}; };

