      "one",
      "two",
      "three",
      "four",
      "five",
      "six",
      "seven",
      "eight",
      "nine",
      "ten",
    ],
  };
};

const _verse = function verse(numberWords) {
  const bottles = (count, capitalized) =>
    `${(capitalized ? numberWords.cap : numberWords.lower)[count]} green bottle${
      count === 1 ? "" : "s"
    }`;
  return (count) =>
    [
      `${bottles(count, true)} hanging on the wall,`,
      `${bottles(count, true)} hanging on the wall,`,
