const _Board = function Board(){
  return class Board {
    constructor(board) {
      // Each row is a string like ". O . X ." — remove all whitespace
      // (leading indentation and inter-cell spaces) to get the raw cells.
      this.cells = board.map((row) => row.replace(/\s+/g, ''));
    }

    winner() {
      const cells = this.cells;
      const rows = cells.length;
      if (rows === 0) return '';
      const cols = cells[0].length;
      if (cols === 0) return '';

      // Hex-grid neighbours: up-left/up-right, left/right, down-left/down-right.
      const dirs = [
        [-1, 0], [-1, 1],
        [0, -1], [0, 1],
        [1, -1], [1, 0],
      ];

      const search = (player, starts, goalReached) => {
        const seen = new Set();
        const stack = [];
        for (const [r, c] of starts) {
          const key = r + ',' + c;
          if (!seen.has(key)) {
            seen.add(key);
            stack.push([r, c]);
          }
        }
        while (stack.length) {
          const [r, c] = stack.pop();
          if (goalReached(r, c)) return true;
          for (const [dr, dc] of dirs) {
            const nr = r + dr;
            const nc = c + dc;
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
              const key = nr + ',' + nc;
              if (!seen.has(key) && cells[nr][nc] === player) {
                seen.add(key);
                stack.push([nr, nc]);
              }
            }
          }
        }
        return false;
      };

      // Player O connects top to bottom.
      const oStarts = [];
      for (let c = 0; c < cols; c++) {
        if (cells[0][c] === 'O') oStarts.push([0, c]);
      }
      if (search('O', oStarts, (r) => r === rows - 1)) return 'O';

      // Player X connects left to right.
      const xStarts = [];
      for (let r = 0; r < rows; r++) {
        if (cells[r][0] === 'X') xStarts.push([r, 0]);
      }
      if (search('X', xStarts, (r, c) => c === cols - 1)) return 'X';

      return '';
    }
  };
};

