//
// Exercise: List Ops — basic list operations implemented WITHOUT using any
// functions from Array.prototype (per the instructions'.append constraint).
// Allowed: array literal `[]`, indexing, destructuring/spread of arrays, loops.
//

const _List = function List()
{
  class List {
    constructor(values = []) {
      this.values = values;
    }

    // append: given two lists, add all items in the second list to the end of the first list
    append(list) {
      const values = [];
      for (const item of this.values) values[values.length] = item;
      for (const item of list.values) values[values.length] = item;
      return new List(values);
    }

    // concat: given a series of lists, combine all items in all lists into one flattened list
    concat(list) {
      const values = [];
      for (const item of this.values) values[values.length] = item;
      for (const item of list.values) {
        if (item instanceof List) {
          for (const sub of item.values) values[values.length] = sub;
        } else {
          values[values.length] = item;
        }
      }
      return new List(values);
    }

    // filter: given a predicate and a list, return the list of all items for which predicate(item) is True
    filter(predicate) {
      const values = [];
      for (const item of this.values) {
        if (predicate(item)) values[values.length] = item;
      }
      return new List(values);
    }

    // map: given a function and a list, return the list of the results of applying function(item) on all items
    map(fn) {
      const values = [];
      for (const item of this.values) values[values.length] = fn(item);
      return new List(values);
    }

    // length: given a list, return the total number of items within it
    length() {
      let count = 0;
      for (const _ of this.values) count += 1;
      return count;
    }

    // foldl: given a function, a list, and an initial accumulator, fold each item into the accumulator from the left
    foldl(fn, acc) {
      for (const item of this.values) acc = fn(acc, item);
      return acc;
    }

    // foldr: given a function, a list, and an initial accumulator, fold each item into the accumulator from the right
    foldr(fn, acc) {
      for (let i = this.length() - 1; i >= 0; i -= 1) acc = fn(acc, this.values[i]);
