    } = {}) {
      // White starts on the bottom rank (rank 1) and black on the top rank (rank 8),
      // both on the d-file (column 3). Rows are zero-indexed from the top: rank 1 -> row 7.
      whiteRow = whiteRow === undefined ? 7 : whiteRow;
      whiteColumn = whiteColumn === undefined ? 3 : whiteColumn;
      blackRow = blackRow === undefined ? 0 : blackRow;
      blackColumn = blackColumn === undefined ? 3 : blackColumn;

      if (!onBoard(whiteRow, whiteColumn) || !onBoard(blackRow, blackColumn)) {
        throw new Error('Queen must be placed on the board');
      }
      if (whiteRow === blackRow && whiteColumn === blackColumn) {
        throw new Error('Queens cannot share the same space');
      }

      this.white = [whiteRow, whiteColumn];
      this.black = [blackRow, blackColumn];
    }

    toString() {
      const rows = [];
      for (let r = 0; r < 8; r++) {
