// The input is an array of equal-length lines (or a single multi-line string).
// A rectangle is four '+' corners joined by '-' (top/bottom) and '|' (left/right).

const _toGrid = function toGrid(){
  // Normalize the diagram (string or array of lines) into a 2-D grid of characters.
  return (diagram) => {
    const lines = typeof diagram === "string"
      ? diagram.replace(/\n+$/, "").split("\n")
      : (diagram || []);
    return lines.map((line) => line.split(""));
  };
};

const _isRectangle = function isRectangle(){
  // True when the four '+' corners (r1,c1) and (r2,c2) form an unbroken rectangle:
  // horizontal edges on rows r1/r2, vertical edges on columns c1/c2.
  const horizontal = (grid, r, c) => grid[r][c] === "+" || grid[r][c] === "-";
  const vertical = (grid, r, c) => grid[r][c] === "+" || grid[r][c] === "|";
  return (grid, r1, c1, r2, c2) => {
    for (let c = c1; c <= c2; c++) {
      if (!horizontal(grid, r1, c) || !horizontal(grid, r2, c)) return false;
    }
    for (let r = r1; r <= r2; r++) {
      if (!vertical(grid, r, c1) || !vertical(grid, r, c2)) return false;
    }
