    // bucket is empty and the other bucket is full.
    const forbidden = (a, b) =>
      startBucket === 'one'
        ? (a === 0 && b === bucketTwo)
        : (b === 0 && a === bucketOne);

    const match = (a, b) => {
      if (a === goal) return { goalBucket: 'one', otherBucket: b };
      if (b === goal) return { goalBucket: 'two', otherBucket: a };
      return null;
    };

    // First action: fill the starting bucket.
    const startA = startBucket === 'one' ? bucketOne : 0;
    const startB = startBucket === 'one' ? 0 : bucketTwo;

    const first = match(startA, startB);
    if (first) return { moves: 1, goalBucket: first.goalBucket, otherBucket: first.otherBucket };

    const visited = new Set([`${startA},${startB}`]);
    let frontier = [[startA, startB, 1]];

    while (frontier.length) {
      const next = [];
      for (const [a, b, moves] of frontier) {
        const states = [];

        // Pour bucket one into bucket two until one is empty / the other full.
        const pourAB = Math.min(a, bucketTwo - b);
        if (pourAB > 0) states.push([a - pourAB, b + pourAB]);

        // Pour bucket two into bucket one.
        const pourBA = Math.min(b, bucketOne - a);
        if (pourBA > 0) states.push([a + pourBA, b - pourBA]);

        // Empty a bucket.
        if (a > 0) states.push([0, b]);
        if (b > 0) states.push([a, 0]);

        // Fill a bucket.
        if (a < bucketOne) states.push([bucketOne, b]);
        if (b < bucketTwo) states.push([a, bucketTwo]);

        for (const [na, nb] of states) {
          if (forbidden(na, nb)) continue;
          const key = `${na},${nb}`;
          if (visited.has(key)) continue;
          visited.add(key);
          const hit = match(na, nb);
          if (hit) return { moves: moves + 1, goalBucket: hit.goalBucket, otherBucket: hit.otherBucket };
